    cartelPrender: ["El cartel lleva el código QR del enlace en vivo del evento, y está apagado. ¿Prenderlo?", "The poster carries the QR code of the event's live link, and it is off. Turn it on?"],
    firmasTitulo: ["Firmas del acta", "Signatures on the minutes"],
    firmasTexto: ["Quien firma el acta del congresillo puede hacerlo acá, con el dedo o el mouse, o desde su celular. La firma va como imagen en el PDF; las que falten quedan con la línea para firmar a mano.", "Whoever signs the minutes can do it here, with a finger or the mouse, or from their phone. The signature goes into the PDF as an image; any missing ones keep the line to sign by hand."],
    firmarAqui: ["Firmar en esta pantalla", "Sign on this screen"],
    firmarCelular: ["Firmar desde un celular", "Sign from a phone"],
    firmarCelularApagar: ["Dejar de recibir firmas", "Stop receiving signatures"],
    firmarCelularAyuda: ["Ábrelo en el celular de quien firma, con esta página abierta acá. Cada firma que llega se pregunta antes de ponerla en el acta.", "Open it on the signer's phone while this page is open here. Each signature that arrives is confirmed before going into the minutes."],
    firmaCargo: ["Firma como", "Signs as"],
    firmaNombre: ["Nombre completo", "Full name"],
    firmaRecuadro: ["Firma en el recuadro", "Sign in the box"],
    firmaBorrar: ["Borrar la firma", "Clear the signature"],
    firmaGuardar: ["Guardar la firma", "Save the signature"],
    firmaGuardada: ["Firma de {n} guardada en el acta.", "Signature of {n} saved in the minutes."],
    firmaFaltaNombre: ["Escribe el nombre de quien firma.", "Type the signer's name."],
    firmaFaltaFirma: ["Falta la firma en el recuadro.", "The signature is missing in the box."],
    firmaLlego: ["Llegó la firma de {n} como {c}. ¿Agregarla al acta?", "A signature from {n} as {c} arrived. Add it to the minutes?"],
    firmaAgregar: ["Agregarla al acta", "Add it to the minutes"],
    firmaMandar: ["Mandar la firma", "Send the signature"],
    firmaMandando: ["Mandando… espera a que el árbitro la confirme.", "Sending… wait for the arbiter to confirm it."],
    firmaRecibida: ["Listo: tu firma quedó en el acta.", "Done: your signature is in the minutes."],
    firmaNegada: ["El árbitro no la agregó. Revisa los datos y vuelve a mandarla si hace falta.", "The arbiter did not add it. Check the details and send it again if needed."],
    adjuntoNotaTitulo: ["Nota para el informe", "Note for the report"],
    adjuntoNotaTexto: ["Lo que pasó en tus mesas (un reclamo, una decisión): llega al árbitro principal con tu nombre y va al informe oficial.", "What happened at your boards (a claim, a decision): it reaches the chief arbiter with your name and goes into the official report."],
    adjuntoNotaNombre: ["Tu nombre", "Your name"],
    adjuntoNotaQue: ["Qué pasó", "What happened"],
    adjuntoNotaMandar: ["Mandar la nota", "Send the note"],
