    adjuntoNotaRecibida: ["Listo: la nota llegó al árbitro principal.", "Done: the note reached the chief arbiter."],
    verRelojRonda: ["Ronda {r} · empezó a las {h} · lleva {l}", "Round {r} · started at {h} · {l} played"],
    verRelojFaltan: ["Faltan {n} mesas por terminar: {l}", "{n} boards still playing: {l}"],
    verRelojFaltanUno: ["Falta 1 mesa por terminar: {l}", "1 board still playing: {l}"],
