  function t(idioma, clave, vars) {
    // Con {n} = 1, la versión en singular si la hay («Falta 1 resultado»).
    if (vars && Number(vars.n) === 1 && TEXTOS[clave + "Uno"]) clave += "Uno";
    const par = TEXTOS[clave];
    let s = par ? par[idioma === "en" ? 1 : 0] : clave;
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.split("{" + k + "}").join(String(v));
    return s;
  }

  const api = { TEXTOS, t };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else raiz.PareoTextos = api;
